<template><main class="induction-booking"><section class="booking-shell"><span class="demo-data-badge">Frontend demo · token is not secure</span><h1>Book your induction</h1><div v-if="!invite||blocked" class="booking-state"><h2>{{blocked?.title||'Invitation unavailable'}}</h2><p>{{blocked?.message||'This invitation link is not recognised.'}}</p></div><template v-else><ol class="booking-progress" aria-label="Booking progress"><li v-for="(x,i) in steps" :key="x" :class="{active:step===i+1,complete:step>i+1}">{{i+1}}. {{x}}</li></ol><section v-if="invite.accountState!=='complete'" class="booking-card"><h2>Account required</h2><p>Create or sign in before booking. Authentication and verified-email matching are simulated.</p><button @click="account(true)">Simulate account completion</button><button class="secondary" @click="account(false)">Simulate email mismatch</button></section><section v-else-if="!invite.emailMatch" class="booking-card"><h2>Email/account mismatch</h2><p>The verified account does not match the accepted application.</p><button @click="account(true)">Simulate matching account</button></section><section v-else-if="existing&&!rescheduling" class="booking-card"><h2>Your induction booking</h2><p>{{existing.date}} · {{existing.startTime}}–{{existing.endTime}} {{existing.timeZone}} · {{existing.assignedStaff}}</p><button @click="reschedule">Reschedule</button><button class="secondary" @click="cancelOpen=true">Cancel</button></section><section v-else-if="confirmed" class="booking-card"><h2>Induction booked</h2><p>{{confirmed.date}} · {{confirmed.startTime}}–{{confirmed.endTime}} {{confirmed.timeZone}} with {{confirmed.assignedStaff}}.</p><p>A real Outlook invitation and email would be sent in production. Neither was sent.</p></section><section v-else class="booking-card"><template v-if="step===1"><h2>Confirm your time zone</h2><p>Detected: <strong>{{detectedZone}}</strong></p><label>Time zone<select v-model="selection.timeZone"><option v-for="z in zones" :key="z">{{z}}</option></select></label><p>All induction times will be shown in {{selection.timeZone}}.</p><button @click="step=2">Continue</button></template><template v-else-if="step===2"><h2>Select a date</h2><div class="booking-date-grid"><button v-for="d in dateRange" :key="d" :disabled="!dates.includes(d)" :aria-label="dates.includes(d)?`Select ${d}`:`${d}, unavailable`" @click="chooseDate(d)">{{d}}<small>{{dates.includes(d)?'Available':'Unavailable'}}</small></button></div><p v-if="!dates.length">No dates are available in this range.</p></template><template v-else-if="step===3"><h2>Select a time</h2><p>{{selection.date}} · {{selection.timeZone}}</p><div class="booking-options"><button v-for="t in times" :key="t.startTime" @click="chooseTime(t)"><strong>{{t.startTime}}–{{t.endTime}}</strong><small>{{t.duration}} minutes · {{t.staffCount}} staff available</small></button></div><button class="secondary" @click="step=2">Change date</button></template><template v-else-if="step===4"><h2>Select induction staff</h2><div class="booking-options"><button v-for="s in staff" :key="s.id" :class="{selected:selection.staffId===s.id}" @click="selection.staffId=s.id"><strong>{{s.name}}</strong><span>{{s.role}}</span><small>{{s.intro}} · {{s.languages.join(', ')}}</small></button></div><button :disabled="!selection.staffId" @click="step=5">Review</button></template><template v-else><h2>Review and confirm</h2><dl><div><dt>Meeting</dt><dd>Induction</dd></div><div><dt>Applicant</dt><dd>{{invite.applicantName}}</dd></div><div><dt>Date/time</dt><dd>{{selection.date}} · {{selection.startTime}}–{{selection.endTime}}</dd></div><div><dt>Time zone</dt><dd>{{selection.timeZone}}</dd></div><div><dt>Staff</dt><dd>{{selectedStaff?.name}}</dd></div><div><dt>Duration</dt><dd>60 minutes</dd></div></dl><label><input v-model="collisionDemo" type="checkbox"/> Simulate a final-recheck collision</label><p v-if="collision" role="alert">Availability changed. Your date and time were preserved; select another available staff member, or choose another time if none remain.</p><button @click="confirm">Confirm after final availability recheck</button><button class="secondary" @click="step=4">Change staff</button></template></section></template><DemoActionModal v-if="cancelOpen" title="Cancel booking" field-label="Cancellation reason" confirm-label="Cancel booking" @cancel="cancelOpen=false" @confirm="cancelBooking"/></section></main></template>
<script>
import DemoActionModal from '../Admin/AdminApplications/components/DemoActionModal.vue'; import { availableDates, availableStaff, availableTimes, cancelApplicantBooking, confirmBooking, invitation, simulateAccount } from '../Admin/Bookings/bookingAvailabilityData.js'; import { demoWorkflow } from '../Admin/AdminApplications/applicationAdminData.js';
export default { name:'InductionBooking', components:{DemoActionModal}, props:{invitationToken:{type:String,required:true}}, data(){return{workflow:demoWorkflow,step:1,rescheduling:false,confirmed:null,collision:false,collisionDemo:false,cancelOpen:false,selection:{timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone||'Europe/London',date:'',startTime:'',endTime:'',staffId:''},zones:['Europe/London','Europe/Paris','America/New_York'],steps:['Time zone','Date','Time','Staff','Review']}}, computed:{invite(){return invitation(this.invitationToken)},blocked(){if(!this.invite)return null;if(['expired','revoked'].includes(this.invite.state))return{title:`Invitation ${this.invite.state}`,message:'Request a new invitation from the programme team.'};if(this.invite.state==='used'&&!this.invite.bookingId)return{title:'Invitation already used',message:'This invitation has completed its journey.'};return null},existing(){this.workflow.revision;return this.invite?.bookingId?this.workflow.inductions.find(b=>b.id===this.invite.bookingId):null},detectedZone(){return Intl.DateTimeFormat().resolvedOptions().timeZone||'Europe/London'},dates(){return availableDates()},dateRange(){return Array.from({length:14},(_,i)=>{const d=new Date('2026-09-14T12:00:00');d.setDate(d.getDate()+i);return d.toISOString().slice(0,10)})},times(){return availableTimes(this.selection.date)},staff(){return availableStaff(this.selection.date,this.selection.startTime)},selectedStaff(){return this.staff.find(s=>s.id===this.selection.staffId)}}, methods:{account(match){simulateAccount(this.invitationToken,match)},chooseDate(d){this.selection.date=d;this.step=3},chooseTime(t){Object.assign(this.selection,{startTime:t.startTime,endTime:t.endTime,staffId:''});const s=availableStaff(this.selection.date,t.startTime);if(s.length===1)this.selection.staffId=s[0].id;this.step=4},confirm(){const result=confirmBooking(this.invitationToken,this.selection,{simulateCollision:this.collisionDemo});if(result.collision){this.collision=true;this.collisionDemo=false;this.selection.staffId=result.remainingStaff.length===1?result.remainingStaff[0].id:'';this.step=result.remainingStaff.length?4:3;return}this.confirmed=result.booking;this.rescheduling=false},reschedule(){this.invite.state='valid';this.rescheduling=true;this.step=1},cancelBooking(){cancelApplicantBooking(this.invitationToken);this.cancelOpen=false}} };
</script><style src="./InductionBooking.css"></style>
